    template <typename VectorDataT, typename Y>
    static inline bool compact_collision_check(
        const vamp::collision::Environment<VectorDataT> &environment,
        const Y &y) noexcept
    {
        for (const auto link : geometry_links)
        {
            const auto bounding = (n_spheres + link_bounding_sphere[link]) * 4;
            if (sphere_environment_in_collision(
                    environment, y[bounding], y[bounding + 1], y[bounding + 2], y[bounding + 3]))
            {
                const auto end = link_sphere_start[link] + link_sphere_count[link];
                for (auto sphere = link_sphere_start[link]; sphere < end; ++sphere)
                {
                    const auto offset = sphere * 4;
                    if (sphere_environment_in_collision(
                            environment, y[offset], y[offset + 1], y[offset + 2], y[offset + 3]))
                    {
                        return false;
                    }
                }
            }
        }

        for (const auto pair : allowed_pairs)
        {
            const auto first_bounding = (n_spheres + link_bounding_sphere[pair.first]) * 4;
            const auto second_bounding = (n_spheres + link_bounding_sphere[pair.second]) * 4;
            if (sphere_sphere_self_collision<VectorDataT>(
                    y[first_bounding], y[first_bounding + 1], y[first_bounding + 2], y[first_bounding + 3],
                    y[second_bounding], y[second_bounding + 1], y[second_bounding + 2], y[second_bounding + 3]))
            {
                const auto first_end = link_sphere_start[pair.first] + link_sphere_count[pair.first];
                const auto second_end = link_sphere_start[pair.second] + link_sphere_count[pair.second];
                for (auto first = link_sphere_start[pair.first]; first < first_end; ++first)
                {
                    const auto first_offset = first * 4;
                    for (auto second = link_sphere_start[pair.second]; second < second_end; ++second)
                    {
                        const auto second_offset = second * 4;
                        if (sphere_sphere_self_collision<VectorDataT>(
                                y[first_offset], y[first_offset + 1], y[first_offset + 2], y[first_offset + 3],
                                y[second_offset], y[second_offset + 1], y[second_offset + 2], y[second_offset + 3]))
                        {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

